  function pushUnique(target, items, keyFn) {
    if (!Array.isArray(target) || !Array.isArray(items)) return;
    var seen = Object.create(null);
    target.forEach(function (x) {
      var k = keyFn(x);
      if (k) seen[k] = true;
    });
    items.forEach(function (item) {
      var k = keyFn(item);
      if (!k || !seen[k]) {
        if (k) seen[k] = true;
        target.push(item);
      }
    });
  }

